import { defineStyleConfig } from '@chakra-ui/react';

/**
 * Recipe — cart-line inline status message (SFCC-795 §11.2, plan step 3.2).
 * `.claude/session-notes.md` §11.2: "inline message (error/warning) sits between the stepper and
 * the actions, w-full, `Default/Caption` regular 12px / lh18. In error states the Item Details
 * gap widens 12 -> 16px." (the gap widening is `ZimmCartItem`'s own `hasError` resolution prop —
 * see product-item.css.ts — not this recipe's concern; this file owns only the message's own
 * type/colour.)
 *
 * Single visual node, no independent per-part state — `defineStyleConfig` + `useStyleConfig(...,
 * {variant})` (ZimmNavItem's / ZimmWishlistBadge's pattern) applies directly here, rather than
 * ZimmQuantityStepper's function-form `baseStyle` (which exists there because that recipe has
 * multiple PARTS needing independent values from one shared boolean, not a single Chakra-native
 * `variant` switch).
 *
 * --- Typography: regular weight is a DELIBERATE override, on a DIFFERENT Figma node than the
 * one commit 5 (SFCC-270) corrected — read both before touching either ---
 * `textStyle: 'caption'` supplies the correct 12px size / 18px line-height pair, but this
 * codebase's `caption` textStyle (theme/foundation/typography.ts) is MEDIUM-weight
 * (`fontWeight: fontWeights.medium`) — that is exactly right for Figma's OTHER caption node,
 * `Default/Caption-strong` (the cart-item colour+size line — see
 * item-variant/item-variant.css.ts:73-84, which deliberately keeps `caption` with NO fontWeight
 * override for that reason, having removed an earlier, backwards override). THIS element is
 * Figma's plain, un-strong `Default/Caption` node, which is REGULAR-weight per the session-notes
 * citation above — the opposite correction, on a different string, elsewhere in the same design
 * file. `fontWeight` is therefore set explicitly below to override the textStyle-expanded medium
 * value back down to regular — the same "a direct CSS prop applied after the textStyle expansion
 * wins in Chakra's style pipeline" mechanism zimmButton.css.ts's `sizes.lg`/`sizes.sm` already
 * documents and relies on for the identical reason.
 *
 * `width: 'full'` reproduces Figma's own "w-full" annotation for this element explicitly, rather
 * than relying on this node's flex/stack parent to stretch it by default.
 *
 * No low-stock variant: a separate requirement explicitly forbids low-stock messaging at the
 * cart level (SFCC-795 §11.2 build decisions) — the variants map below only ever has the two
 * keys `error`/`warning`; do not add a third.
 */
const baseStyle = {
  textStyle: 'caption',
  fontWeight: 'var(--zimm-font-weight-regular)',
  width: 'full',
};

const variants = {
  // Figma `text/error` #9c0000 -> status.error (session-notes.md §11.10(6) colour audit).
  error: {
    color: 'var(--zimm-color-status-error)',
  },
  // Figma `text/muted` / `text/subtlest` #969696 -> both collapse onto this one token, no
  // ambiguity in this codebase's own set (session-notes.md §11.10(6)).
  //
  // Max-quantity messaging ("Maximum purchase quantity reached for this size") uses THIS variant,
  // not `error` — even though its own requirement/AC text uses the word "error" to describe it.
  // That word is describing "user-facing feedback" in the requirement's own vocabulary, not
  // asserting the error SEVERITY tier: the actual Figma design and that story's own AC agree the
  // rendered treatment is grey/warning, not red/error. Deliberate word-vs-severity reconciliation,
  // settled at this build's planning gate — not a mistake, and not to be "corrected" back to
  // `error` by a future reader matching the word alone.
  warning: {
    color: 'var(--zimm-color-text-muted)',
  },
};

export const ZimmInlineMessage = defineStyleConfig({
  baseStyle,
  variants,
});

// Source: Zimmermann Design System 2026 (Handover tokens/colors.css).
// Brand primitive and semantic alias colour tokens. The alias tier below
// references the primitive tier via plain object lookups (`grey[900]`)
// rather than retyping each hex value a second time.

const grey = {
  black: 'black',
  900: '#191919',
  800: '#282828',
  700: '#454545',
  600: '#666666',
  500: '#707070',
  300: '#969696',
  200: '#d1d1d1',
  100: '#e6e6e6',
  white: '#ffffff',
};

const ivory = {
  400: '#f2e9e0',
  300: '#fbf5ef',
  200: '#f6f4f1',
  100: '#f9f8f6',
};

const coral = { 500: '#f98f8c' };
const green = { 500: '#2d5a3d' };
const orange = { 500: '#d67600' };
const red = { 500: '#9c0000' };

// Opacity (base: grey/900 #191919)
const opacity = {
  50: 'rgba(25, 25, 25, 0.50)',
  40: 'rgba(25, 25, 25, 0.40)',
  30: 'rgba(25, 25, 25, 0.30)',
  15: 'rgba(25, 25, 25, 0.15)',
};

export const colors = {
  // ---- Brand / Primitive ----
  grey,
  ivory,
  coral,
  green,
  orange,
  red,
  opacity,

  // ---- Alias / Semantic: Background ----
  background: {
    '01': ivory[100],
    '02': ivory[200],
    '03': ivory[300],
    '04': ivory[400],
    '05': grey[900],
    '06': grey[800],
    '07': grey.white,
  },
  // ---- Alias / Semantic: Text ----
  text: {
    default: grey[900],
    inverse: grey.white,
    // Handover contradicts itself here: tokens/colors.css says #969696 "confirmed",
    // but tokens.md and contract/zimm-contract.js say #939393 and still flag it
    // unresolved. Shipping the colors.css value (grey[300]); confirm with the UI designer.
    inverseGrey: grey[300],
    secondary: grey[600],
    muted: grey[300],
  },
  // ---- Alias / Semantic: Border ----
  border: {
    default: grey[100],
    secondary: grey[200],
    focus: grey[900],
    forms: grey[500],
    error: red[500], // no Handover counterpart; retained for form validation use
  },
  // ---- Alias / Semantic: Status ----
  status: {
    success: green[500],
    error: red[500],
    errorBackground: coral[500],
    storeClosed: orange[500],
  },
  // ---- Alias / Semantic: Link ----
  link: {
    default: grey[900],
    hover: grey[500],
  },
  // ---- Alias / Semantic: Icon ----
  icon: {
    default: grey[900],
    disabled: grey[200],
  },
  // ---- Alias / Semantic: Action: Primary ----
  action: {
    primary: {
      bgDefault: grey[900],
      bgHover: grey[300],
      bgPressed: grey[700],
      bgDisabled: grey[200],
      bgFocused: grey.black,
      text: grey.white,
      textDisabled: grey[300],
    },
    secondary: {
      border: grey[900],
      bgHover: ivory[100],
      text: grey[900],
      textInverse: grey.white,
      textDisabled: grey[300],
    },
  },
};

